mapper.select:
SELECT id, conversation_id, user_id, project_id, title, status, state_generation, memory_summary, summarized_through_message_id, created_at, updated_at, created_by, updated_by FROM manga_creative_conversation WHERE user_id = #{userId}
AND project_id = #{projectId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

mapper.update:
UPDATE manga_creative_conversation SET state_generation = state_generation + 1,
    updated_by = #{actor}
WHERE conversation_id = #{conversationId} AND state_generation = #{generation}
